// Parse Input: extract the rug category (and optional "focus:" line) from chat.
const input = $input.first().json.chatInput || '';

const categories = [
  { key: 'area_rug', display: 'Area Rug', patterns: ['area rug', 'area rugs'] },
  { key: 'outdoor_rug', display: 'Outdoor Rug', patterns: ['outdoor rug', 'outdoor rugs', 'patio rug'] },
  { key: 'hallway_runner', display: 'Hallway Runner', patterns: ['hallway runner', 'runner rug', 'hall runner', 'runners'] },
  { key: 'shag_rug', display: 'Shag Rug', patterns: ['shag rug', 'shag rugs', 'shaggy rug'] }
];

const lowerInput = input.toLowerCase();
let match = null;
for (const cat of categories) {
  if (cat.patterns.some(p => lowerInput.includes(p))) { match = cat; break; }
}

const focusMatch = input.match(/focus\s*:\s*([^\n]+)/i);
const focus = focusMatch ? focusMatch[1].trim() : '';

return [{
  json: {
    selectedCategory: match ? match.display : null,
    categoryKey: match ? match.key : null,
    focus,
    hasValidInput: !!match,
    errorReason: match ? null : 'no_category'
  }
}];

// Error Response: explain in chat why no report was produced.
const input = $input.first().json;
const reason = input.errorReason || 'unknown';

let message;
if (reason === 'no_category') {
  message = 'I could not detect a rug category. Send one of: Area Rug, Outdoor Rug, Hallway Runner, Shag Rug. Optionally add a second line such as "focus: washable".';
} else if (reason === 'missing_retailer_data') {
  message = 'No report was generated: the product API returned no usable products for ' + (input.missingRetailers || []).join(', ') +
    '. A competitor comparison needs Wayfair, Amazon and Walmart data. Try again in a few minutes.';
} else {
  message = 'An unknown error occurred. Check the execution log in n8n.';
}

return [{ json: { error: true, reason, output: message } }];

// Collect Sections: gather every agent's HTML plus the computed data.
// Node names here must match the agent node names exactly (case-sensitive).
const AGENTS = {
  executive: 'Executive Summary Agent',
  competitors: 'Competitor Analysis Agent',
  comparison: 'Comparison Agent',
  pricing: 'Pricing & Whitespace Agent',
  suppliers: 'Supplier Identification Agent',
  recommendations: 'Recommendations Agent'
};

const sections = {};
for (const [key, nodeName] of Object.entries(AGENTS)) {
  try { sections[key] = String($(nodeName).first().json.output || ''); } catch (e) { sections[key] = ''; }
}

const data = $('Compute Competitor Metrics').first().json;

return [{
  json: {
    sections,
    metadata: {
      category: data.category,
      categoryKey: data.categoryKey,
      focus: data.focus,
      snapshot: data.snapshot,
      date: new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' })
    },
    metrics: data.metrics,
    products: data.products
  }
}];

// Assemble HTML Report
// Cleans each agent section, adds code-built tables (comparison + product appendix),
// and wraps everything in one styled, self-contained HTML page.
var data = $input.first().json;
var sections = data.sections || {};
var meta = data.metadata || {};
var metrics = data.metrics || {};
var products = data.products || [];
var R = metrics.retailers || {};
var RETAILERS = ['wayfair', 'amazon', 'walmart'];

function esc(s) {
  return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function money(x) { return x == null ? 'n/a' : '$' + Number(x).toFixed(2); }

// ---- 1. Strip model chatter before/after each <section> ----
Object.keys(sections).forEach(function (k) {
  var s = String(sections[k] || '').replace(/```html\s*/gi, '').replace(/```\s*/g, '').replace(/\\n/g, '\n').replace(/\\"/g, '"');
  var a = s.indexOf('<section');
  var b = s.lastIndexOf('</section>');
  sections[k] = (a > -1 && b > a) ? s.slice(a, b + 10) : '';
});

// ---- 2. Formatting cleanup (from the Phase 2 report): Markdown -> HTML, no italics, hashtag pills ----
var CATEGORY_NAMES = { area_rug: 'Area Rug', outdoor_rug: 'Outdoor Rug', hallway_runner: 'Hallway Runner', shag_rug: 'Shag Rug' };
function fixText(t) {
  t = t.replace(/(^|\n)[ \t]*#{1,6}[ \t]+([^\n]+)/g, function (m, pre, h) { return pre + '<h4>' + h.trim() + '</h4>'; });
  t = t.replace(/\*\*([^*\n]{1,200}?)\*\*/g, '<strong>$1</strong>');
  t = t.replace(/__([^_\n]{1,200}?)__/g, '<strong>$1</strong>');
  t = t.replace(/(^|[\s(>])\*([^*\s][^*\n]{0,150}?)\*(?=[\s.,;:!?)<]|$)/g, '$1$2');
  t = t.replace(/\*\*/g, '');
  t = t.replace(/(?:^|\n)((?:[ \t]*[-•*][ \t]+[^\n]+(?:\n|$))+)/g, function (m, block) {
    var items = block.split('\n').map(function (l) { return l.replace(/^[ \t]*[-•*][ \t]+/, '').trim(); }).filter(Boolean);
    return '\n<ul>' + items.map(function (i) { return '<li>' + i + '</li>'; }).join('') + '</ul>\n';
  });
  t = t.replace(/\b(area_rug|outdoor_rug|hallway_runner|shag_rug)\b/g, function (m) { return CATEGORY_NAMES[m] || m; });
  t = t.replace(/(^|[\s(>,])#([A-Za-z][A-Za-z0-9_]{1,40})\b/g, function (m, pre, tag) {
    if (/^[0-9a-fA-F]{3,8}$/.test(tag)) return m;
    return pre + '<span class="hashtag">#' + tag + '</span>';
  });
  return t;
}
function formatFix(html) {
  var keep = [];
  html = html.replace(/<(style|script)[\s\S]*?<\/\1>/gi, function (m) { keep.push(m); return '\u0000' + (keep.length - 1) + '\u0000'; });
  var parts = html.split(/(<[^>]+>)/);
  for (var i = 0; i < parts.length; i++) { if (parts[i] && parts[i].charAt(0) !== '<') parts[i] = fixText(parts[i]); }
  html = parts.join('');
  html = html.replace(/<\/?(em|i)(\s[^>]*)?>/gi, '');
  return html.replace(/\u0000(\d+)\u0000/g, function (m, n) { return keep[+n]; });
}
Object.keys(sections).forEach(function (k) { sections[k] = formatFix(sections[k]); });

// ---- 3. Visible placeholder for any section an agent failed to produce ----
var TITLES = {
  executive: 'Executive Summary', competitors: 'Competitor Analysis', comparison: 'Head-to-Head Comparison',
  pricing: 'Pricing & Whitespace', suppliers: 'Supplier Identification', recommendations: 'Recommendations'
};
var missingSections = [];
Object.keys(TITLES).forEach(function (k) {
  if (!sections[k]) {
    missingSections.push(TITLES[k]);
    sections[k] = '<section class="section-missing"><h2>' + esc(TITLES[k]) + '</h2><p>This section was not generated in this run: the AI agent returned no usable HTML. Check the agent node in the n8n execution and rerun.</p></section>';
  }
});

// ---- 4. Code-built comparison table (exact numbers, never AI-written) ----
function row(label, fn, note) {
  return '<tr><th scope="row">' + esc(label) + (note ? '<span class="row-note">' + esc(note) + '</span>' : '') + '</th>' +
    RETAILERS.map(function (r) { return '<td' + (r === 'wayfair' ? ' class="us"' : '') + '>' + fn(R[r] || {}) + '</td>'; }).join('') + '</tr>';
}
function ofN(key, name) {
  return function (x) { return ((x[key] || {})[name] || 0) + ' of ' + (x.listings || 0); };
}
var FEATURE_ROWS = ['Washable', 'Non-slip backing', 'Indoor/outdoor', 'Shag / high pile', 'Low pile / flatweave', 'Natural fiber', 'Designer collaboration'];
var comparisonTable =
  '<div class="table-wrap"><table class="data-table compare-table"><thead><tr><th>Metric</th><th class="us">Wayfair</th><th>Amazon</th><th>Walmart</th></tr></thead><tbody>' +
  row('Listings analyzed', function (x) { return x.listings; }) +
  row('Price range', function (x) { return money(x.priceMin) + ' to ' + money(x.priceMax); }) +
  row('Median price', function (x) { return money(x.priceMedian); }) +
  row('Average price', function (x) { return money(x.priceMean); }) +
  row('Median price per sq ft', function (x) { return x.medianPricePerSqft == null ? 'n/a' : money(x.medianPricePerSqft); }, 'listings with size in title') +
  row('Listings with size in title', function (x) { return x.listingsWithSize + ' of ' + x.listings; }) +
  row('Average rating', function (x) { return x.avgRating == null ? 'n/a' : x.avgRating.toFixed(2); }) +
  row('Median review count', function (x) { return x.medianReviews == null ? 'n/a' : Math.round(x.medianReviews).toLocaleString('en-US'); }) +
  row('Total reviews', function (x) { return (x.totalReviews || 0).toLocaleString('en-US'); }) +
  row('Listings with under 10 reviews', function (x) { return x.listingsUnder10Reviews + ' of ' + x.listings; }) +
  FEATURE_ROWS.map(function (f) { return row(f, ofN('features', f)); }).join('') +
  '</tbody></table></div>' +
  '<p class="table-note">Computed directly from the sampled listings. Counts, not market share.</p>';

var bandTable =
  '<div class="table-wrap"><table class="data-table"><thead><tr><th>Price band</th><th class="us">Wayfair</th><th>Amazon</th><th>Walmart</th></tr></thead><tbody>' +
  ((R.wayfair && R.wayfair.priceBands) || []).map(function (b, i) {
    return '<tr><th scope="row">' + esc(b.band) + '</th>' + RETAILERS.map(function (r) {
      var c = R[r].priceBands[i].count;
      return '<td' + (r === 'wayfair' ? ' class="us"' : '') + '>' + (c ? c : '<span class="zero">0</span>') + '</td>';
    }).join('') + '</tr>';
  }).join('') +
  '</tbody></table></div>';

function injectAfterH2(html, block) {
  var m = html.match(/<\/h2>/i);
  if (!m) return html.replace(/<section[^>]*>/i, function (s) { return s + block; });
  var idx = html.indexOf(m[0]) + m[0].length;
  return html.slice(0, idx) + block + html.slice(idx);
}
sections.comparison = injectAfterH2(sections.comparison, comparisonTable);
sections.pricing = injectAfterH2(sections.pricing, '<h3>Listings by price band</h3>' + bandTable);

// ---- 5. Product appendix: every listing the report is based on ----
var appendix =
  '<section class="appendix"><h2>Appendix: Listings Analyzed</h2>' +
  '<p>Product IDs cited in this report (for example AZ3) refer to the rows below. Brand is inferred from the listing title.</p>' +
  '<div class="table-wrap"><table class="data-table product-table"><thead><tr><th>ID</th><th>Retailer</th><th>Product</th><th>Price</th><th>Rating</th><th>Reviews</th><th>Size</th><th>Brand</th></tr></thead><tbody>' +
  products.map(function (p) {
    var name = esc(p.title.length > 90 ? p.title.slice(0, 87) + '...' : p.title);
    return '<tr class="r-' + p.retailer + '"><td class="pid">' + esc(p.id) + '</td><td>' + esc(p.retailerLabel) + '</td>' +
      '<td>' + (p.url ? '<a href="' + esc(p.url) + '" target="_blank" rel="noopener">' + name + '</a>' : name) + (p.variant ? '<span class="variant">' + esc(p.variant) + '</span>' : '') + '</td>' +
      '<td>' + money(p.price) + '</td><td>' + (p.rating == null ? 'n/a' : p.rating) + '</td>' +
      '<td>' + (p.reviews == null ? 'n/a' : Number(p.reviews).toLocaleString('en-US')) + '</td>' +
      '<td>' + esc(p.size || '') + '</td><td>' + esc(p.brand || '') + '</td></tr>';
  }).join('') +
  '</tbody></table></div></section>';

// ---- 6. Page shell ----
var CSS = [
  ':root{--primary:#7C3AED;--primary-dark:#5B21B6;--primary-light:#A78BFA;--secondary:#1F2937;--accent:#F59E0B;--success:#10B981;--danger:#EF4444;--bg:#F9FAFB;--card:#FFFFFF;--border:#E5E7EB;--text:#1F2937;--muted:#6B7280;--us:#F5F3FF}',
  '*{margin:0;padding:0;box-sizing:border-box}',
  'body{font-family:Inter,-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:var(--text);background:var(--bg)}',
  '.report-container{max-width:1040px;margin:0 auto;padding:40px 24px}',
  '.report-header{background:linear-gradient(135deg,var(--primary) 0%,var(--primary-dark) 100%);color:#fff;padding:44px 40px;border-radius:16px;margin-bottom:28px}',
  '.report-header h1{font-size:30px;font-weight:700;margin-bottom:6px}',
  '.report-header .subtitle{font-size:16px;opacity:.92}',
  '.report-header .meta{margin-top:14px;font-size:13px;opacity:.85}',
  '.report-toc{display:flex;flex-wrap:wrap;gap:8px;margin-bottom:24px}',
  '.report-toc a{font-size:12px;font-weight:600;color:var(--primary-dark);background:#EDE9FE;padding:6px 12px;border-radius:999px;text-decoration:none}',
  'section{background:var(--card);border-radius:12px;padding:32px;margin-bottom:24px;box-shadow:0 1px 3px rgba(0,0,0,.08)}',
  'section h2{font-size:22px;font-weight:600;color:var(--secondary);margin-bottom:20px;padding-bottom:12px;border-bottom:2px solid var(--primary-light)}',
  'section h3{font-size:16px;font-weight:600;color:var(--primary);margin:24px 0 12px}',
  'section h4{font-size:14px;font-weight:600;color:var(--secondary);margin-bottom:6px}',
  'p{margin-bottom:12px}ul,ol{margin-left:20px;margin-bottom:16px}li{margin-bottom:6px}',
  'a{color:var(--primary-dark)}',
  '.summary-hero{background:linear-gradient(135deg,var(--bg) 0%,#EDE9FE 100%);border-radius:12px;padding:24px;margin-bottom:24px}',
  '.key-insight{border-left:4px solid var(--primary);padding-left:16px}',
  '.key-insight .label{font-size:11px;font-weight:600;color:var(--primary);text-transform:uppercase;letter-spacing:.04em}',
  '.key-insight p{font-size:17px;font-weight:500;margin:8px 0 0}',
  '.retailer-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}',
  '.retailer-card{background:var(--bg);border:1px solid var(--border);border-radius:10px;padding:20px}',
  '.retailer-card.wayfair{background:var(--us);border-color:var(--primary-light)}',
  '.retailer-card h3{margin-top:0}',
  '.retailer-card ul{margin-left:16px;font-size:13px}',
  '.threat{display:inline-block;font-size:11px;font-weight:700;text-transform:uppercase;padding:3px 9px;border-radius:999px;margin-bottom:10px}',
  '.threat.high{background:#FEE2E2;color:#B91C1C}.threat.medium{background:#FEF3C7;color:#B45309}.threat.low{background:#D1FAE5;color:#047857}.threat.baseline{background:#EDE9FE;color:var(--primary-dark)}',
  '.table-wrap{overflow-x:auto;margin:12px 0 8px}',
  '.data-table{width:100%;border-collapse:collapse;font-size:13px}',
  '.data-table th,.data-table td{padding:9px 12px;border-bottom:1px solid var(--border);text-align:left;vertical-align:top}',
  '.data-table thead th{background:var(--secondary);color:#fff;font-weight:600;font-size:12px}',
  '.data-table thead th.us{background:var(--primary)}',
  '.data-table td.us{background:var(--us);font-weight:600}',
  '.data-table tbody th{font-weight:500;color:var(--secondary)}',
  '.row-note{display:block;font-size:11px;color:var(--muted);font-weight:400}',
  '.zero{color:var(--danger);font-weight:700}',
  '.table-note{font-size:12px;color:var(--muted)}',
  '.win-lose-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px;margin-top:8px}',
  '.win-lose-grid>div{border-radius:10px;padding:18px}',
  '.wins{background:#ECFDF5;border-left:4px solid var(--success)}.gaps{background:#FEF2F2;border-left:4px solid var(--danger)}',
  '.opportunity-card{background:var(--bg);border:1px solid var(--border);border-left:4px solid var(--accent);border-radius:8px;padding:18px;margin-bottom:14px}',
  '.opportunity-action{font-weight:500;color:var(--secondary);margin-bottom:0}',
  '.rec-list{display:grid;gap:14px}',
  '.rec-item{display:flex;gap:16px;padding:20px;background:var(--bg);border-radius:10px}',
  '.rec-number{width:32px;height:32px;background:var(--primary);color:#fff;border-radius:50%;display:flex;align-items:center;justify-content:center;font-weight:700;flex-shrink:0}',
  '.rec-priority{display:inline-block;font-size:11px;font-weight:700;text-transform:uppercase;padding:3px 9px;border-radius:999px;margin-bottom:8px}',
  '.rec-priority.act{background:#FEE2E2;color:#B91C1C}.rec-priority.test{background:#FEF3C7;color:#B45309}.rec-priority.watch{background:#E0E7FF;color:#3730A3}',
  '.section-missing{border:2px dashed var(--danger);background:#FEF2F2}',
  '.product-table td{font-size:12px}.pid{font-weight:700;white-space:nowrap}',
  '.variant{display:block;font-size:11px;color:var(--muted)}',
  '.r-wayfair td:first-child{border-left:3px solid var(--primary)}',
  '.hashtag{display:inline-block;padding:1px 9px;margin:1px 2px;border-radius:999px;background:#eef3f8;color:#2b5d8a;font-size:.88em;font-weight:600;white-space:nowrap;line-height:1.6}',
  '.report-footer{text-align:center;padding:28px;color:var(--muted);font-size:12px}',
  '@media (max-width:768px){.retailer-grid,.win-lose-grid{grid-template-columns:1fr}.report-header{padding:28px 22px}.report-header h1{font-size:23px}section{padding:22px}}',
  '@media print{body{background:#fff}.report-toc{display:none}section{box-shadow:none;break-inside:avoid-page}}'
].join('\n');

var ORDER = [
  ['executive', 'Executive Summary'], ['competitors', 'Competitors'], ['comparison', 'Comparison'],
  ['pricing', 'Pricing & Whitespace'], ['suppliers', 'Suppliers'], ['recommendations', 'Recommendations']
];
var body = ORDER.map(function (o) {
  return sections[o[0]].replace(/<section/i, '<section id="' + o[0] + '"');
}).join('\n');
var toc = '<nav class="report-toc">' + ORDER.map(function (o) { return '<a href="#' + o[0] + '">' + esc(o[1]) + '</a>'; }).join('') + '<a href="#appendix">Listings</a></nav>';

var counts = RETAILERS.map(function (r) { return (R[r] ? R[r].listings : 0) + ' ' + (R[r] ? R[r].label : r); }).join(', ');
var title = esc(meta.category) + ' Competitor Report';
var html = '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0">' +
  '<title>' + title + '</title>' +
  '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">' +
  '<style>' + CSS + '</style></head><body><div class="report-container">' +
  '<header class="report-header"><h1>' + title + '</h1>' +
  '<p class="subtitle">Wayfair vs. Amazon vs. Walmart: pricing, assortment, whitespace and supplier leads</p>' +
  '<p class="meta">Generated ' + esc(meta.date) + ' | Listings analyzed: ' + esc(counts) + ' | Data snapshot: ' + esc(meta.snapshot) +
  (meta.focus ? ' | Focus: ' + esc(meta.focus) : '') + '</p></header>' +
  toc + '<main>' + body + appendix.replace('<section class="appendix"', '<section id="appendix" class="appendix"') + '</main>' +
  '<footer class="report-footer"><p>Wayfair Competitor Monitoring Agent | Phase 3</p>' +
  '<p>All figures are computed from the sampled listings above. No sales, traffic or conversion data was used.</p></footer>' +
  '</div></body></html>';

return [{ json: { cleanedHtml: html, missingSections: missingSections } }];

// Validate Report: check every section made it in and flag content worth a human look.
const input = $input.first().json;
const html = input.cleanedHtml || '';

const required = {
  'Executive Summary': 'id="executive"',
  'Competitor Analysis': 'id="competitors"',
  'Comparison': 'id="comparison"',
  'Pricing & Whitespace': 'id="pricing"',
  'Supplier Identification': 'id="suppliers"',
  'Recommendations': 'id="recommendations"'
};

const warnings = [];
const sectionsFound = Object.keys(required).filter(k => html.includes(required[k]));
const missing = input.missingSections || [];
missing.forEach(s => warnings.push('Section not generated: ' + s));
if (!html.includes('</html>')) warnings.push('HTML may be truncated');

// Visible text only (drop the <style> block and tags)
const text = html.replace(/<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ');
if (/\*\*|```/.test(text)) warnings.push('Leftover Markdown found');

// Percentages are allowed only next to a count; list them so a human can check.
const percents = text.match(/[^.]{0,60}\d+(?:\.\d+)?\s?%[^.]{0,40}/g) || [];
if (percents.length) warnings.push(percents.length + ' percentage claim(s) to double-check, e.g. "' + percents[0].replace(/^\S*\s+/, '').trim() + '"');

return [{
  json: {
    cleanedHtml: html,
    validation: {
      isValid: missing.length === 0 && html.includes('</html>'),
      sectionsGenerated: (sectionsFound.length - missing.length) + ' of ' + Object.keys(required).length,
      warnings
    }
  }
}];

// Download Report: turn the HTML into a downloadable file and reply in chat.
const input = $input.first().json;
const html = input.cleanedHtml || '';
const validation = input.validation || {};
const category = $('Parse Input').first().json.selectedCategory || 'Rug';

const dateStr = new Date().toISOString().split('T')[0];
const fileName = category.toLowerCase().replace(/\s+/g, '_') + '_competitor_report_' + dateStr + '.html';

const lines = [
  category + ' competitor report is ready: ' + fileName,
  'Sections generated: ' + (validation.sectionsGenerated || 'unknown') + '.',
  'Download it from this execution: open the "Download Report" node, Binary tab, then Download.'
];
if ((validation.warnings || []).length) lines.push('Warnings: ' + validation.warnings.join(' | '));

return [{
  json: { output: lines.join('\n'), fileName, validation, category, generatedAt: new Date().toISOString() },
  binary: {
    data: {
      data: Buffer.from(html, 'utf8').toString('base64'),
      mimeType: 'text/html',
      fileName
    }
  }
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    wayfair_products: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWayfair: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    amazonProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalAmazonProducts: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// Reshape FastAPI response to the legacy shape that downstream consumers expect.
const r = $input.first().json;
const products = r.products || [];
return [{
  json: {
    walmartProducts: products.map(p => ({
      url: p.url,
      name: p.name,
      price: p.price,
      details: p.details || [],
      pattern: p.pattern || '',
      image_url: p.image_url || '',
      rating: p.rating || '',
      review_count: p.review_count || '',
      scraped_at: r.scraped_at || new Date().toISOString(),
    })),
    totalWalmartProducts: products.length,
    totalProducts: products.length,
    scrapedAt: r.scraped_at || new Date().toISOString(),
  },
}];

// SCOPE GENERATOR - No AI, just JavaScript
